const p = $json.body || {};
if (!p.company) throw new Error('company is required');

const q = [p.company, p.city, p.country].filter(Boolean).join(' ');

const existingSources = [];
if (p.source) existingSources.push(p.source);
if (p.website) existingSources.push('Existing website');

return [{
  json: {
    ...p,
    searchQuery: q,
    sources: [...new Set(existingSources)],
    candidateWebsite: p.website || '',
    candidatePhone: p.phone || '',
    candidateEmail: p.email || '',
    wikidata: p.wikidata || '',
    osmId: p.id || p.osm_id || ''
  }
}];

const src = $('Prepare Enrichment').first().json;
const raw = $input.first().json;

let html = '';
if (typeof raw === 'string') html = raw;
else if (raw && typeof raw.data === 'string') html = raw.data;
else html = JSON.stringify(raw || {});

const emails = [...new Set(
  (html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])
    .filter(e => !/example\.|sentry\.|wixpress\.|cloudflare/i.test(e))
)];

const phones = [...new Set(
  (html.match(/(?:\+?1[\s().-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}/g) || [])
)];

const mailto = [...html.matchAll(/mailto:([^"'?<>\s]+)/gi)].map(m => m[1]);
const tel = [...html.matchAll(/tel:([^"'<>\s]+)/gi)].map(m => m[1]);

const allEmails = [...new Set([...mailto, ...emails])];
const allPhones = [...new Set([...tel, ...phones])];

const links = [...html.matchAll(/href=["']([^"']+)["']/gi)].map(m => m[1]);
const contact = links.find(h => /contact|about|quote|estimate|get-in-touch/i.test(h)) || '';

let contactUrl = '';
if (contact) {
  try {
    contactUrl = new URL(contact, src.candidateWebsite).href;
  } catch {}
}

return [{
  json: {
    ...src,
    website_live: html.length > 200,
    homepageEmail: allEmails[0] || src.candidateEmail || '',
    homepagePhone: allPhones[0] || src.candidatePhone || '',
    contactUrl,
    homepageChecked: true,
    homepageHtmlFound: html.length > 200
  }
}];

const src = $('Extract Website Contacts').first().json;
const raw = $input.first().json;
let html = '';
if (typeof raw === 'string') html = raw;
else if (raw && typeof raw.data === 'string') html = raw.data;
else html = JSON.stringify(raw || {});

const emails = [...new Set(
  [
    ...[...html.matchAll(/mailto:([^"'?<>\s]+)/gi)].map(m => m[1]),
    ...(html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])
  ].filter(e => !/example\.|sentry\.|wixpress\.|cloudflare/i.test(e))
)];

const phones = [...new Set(
  [
    ...[...html.matchAll(/tel:([^"'<>\s]+)/gi)].map(m => m[1]),
    ...(html.match(/(?:\+?1[\s().-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}/g) || [])
  ]
)];

return [{
  json: {
    ...src,
    contactPageChecked: true,
    contactPageEmail: emails[0] || '',
    contactPagePhone: phones[0] || ''
  }
}];

const p = $json;

const website = p.candidateWebsite || '';
const email = p.contactPageEmail || p.homepageEmail || p.candidateEmail || '';
const phone = p.contactPagePhone || p.homepagePhone || p.candidatePhone || '';

let confidence = 0;
const evidence = [];
const provenance = {};

if (p.osmId || (p.sources || []).includes('OpenStreetMap')) {
  confidence += 20;
  evidence.push('OSM record present');
}

if (website) {
  provenance.website = 'OpenStreetMap / existing prospect data';
  confidence += 20;
  evidence.push('Website candidate present');
}

if (p.website_live) {
  confidence += 20;
  evidence.push('Official website reachable');
}

if (email) {
  provenance.email = p.contactPageEmail ? 'Official website contact page' :
                     p.homepageEmail ? 'Official website homepage' :
                     'Existing prospect data';
  confidence += 20;
  evidence.push('Public business email found');
}

if (phone) {
  provenance.phone = p.contactPagePhone ? 'Official website contact page' :
                     p.homepagePhone ? 'Official website homepage' :
                     'Existing prospect data';
  confidence += 15;
  evidence.push('Public business phone found');
}

if (p.contactPageChecked) {
  confidence += 5;
  evidence.push('Contact page checked');
}

confidence = Math.min(confidence, 100);

let verification_status = 'Needs verification';
if (website && p.website_live && (email || phone) && confidence >= 70) {
  verification_status = 'Verified';
} else if (!email && !phone) {
  verification_status = 'Not contactable';
}

return [{
  json: {
    company: p.company,
    city: p.city || '',
    country: p.country || '',
    niche: p.niche || '',
    website,
    email,
    phone,
    verification_status,
    confidence,
    contactable: Boolean(email || phone),
    evidence,
    provenance,
    notes: website
      ? ''
      : 'No official website was supplied by current sources. Generic web discovery was not performed automatically in this free/compliant v2.',
    enriched_at: new Date().toISOString()
  }
}];

const p = $('Prepare Enrichment').first().json;
return [{
  json: {
    ...p,
    website_live: false,
    homepageChecked: false,
    contactPageChecked: false
  }
}];

const p = $json;
return [{
  json: {
    ...p,
    contactPageChecked: false,
    contactPageEmail: '',
    contactPagePhone: ''
  }
}];
